INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('08bd19ee-8904-4ea8-8e1f-81ec1022cb9a', 'Section E. Current role and outcomes', 'R1. What best describes your main current activity?', 'single_choice', '["I run my own business mainly because I had no better job options (necessity entrepreneur)","I run my own business mainly because I saw a good opportunity (opportunity entrepreneur)","I work as an employee (salary or wage)","I am an investor / business angel / venture capitalist","I am a student","I am unemployed","Other"]'::jsonb, NULL, 200, true);
INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('9f513954-e677-4c2d-9f55-a67884150764', 'Section E. Current role and outcomes', 'R2a. Is your business legally registered as a company (LLC/JSC etc.), or are you self-employed without registration?', 'single_choice', '["Legally registered company","Self-employed / unregistered","I do not run a business"]'::jsonb, '{"operator":"OR","rules":[{"questionId":"08bd19ee-8904-4ea8-8e1f-81ec1022cb9a","expectedValue":"I run my own business mainly because I had no better job options (necessity entrepreneur)"},{"questionId":"08bd19ee-8904-4ea8-8e1f-81ec1022cb9a","expectedValue":"I run my own business mainly because I saw a good opportunity (opportunity entrepreneur)"}]}'::jsonb, 210, true);
