INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('2b22b9f1-6517-4e90-ad32-ed82a21e1554', 'Section E. Current role and outcomes', 'R2c. In the last 12 months, what was the approximate total revenue of your business?', 'single_choice', '["Very small (under 10M UZS per year)","Small (10M-50M UZS)","Medium (50M-500M UZS)","Large (above 500M UZS)"]'::jsonb, '{"operator":"OR","rules":[{"questionId":"08bd19ee-8904-4ea8-8e1f-81ec1022cb9a","expectedValue":"I run my own business mainly because I had no better job options (necessity entrepreneur)"},{"questionId":"08bd19ee-8904-4ea8-8e1f-81ec1022cb9a","expectedValue":"I run my own business mainly because I saw a good opportunity (opportunity entrepreneur)"}]}'::jsonb, 230, true);
