INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('7af37b44-598d-4c37-9f99-7bc44e2cc8d8', 'Section F. UzCombinator', 'F0. Have you ever applied to UzCombinator (or seriously considered applying)?', 'single_choice', '["Yes, I applied","I considered applying but did not submit","No"]'::jsonb, NULL, 260, true);
INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('e94f03a9-7181-4e2d-9aef-b283552d7b2c', 'Section F. UzCombinator', 'Q1. What were your main reasons for applying (or considering applying)?', 'multiple_choice', '["Access to mentoring and know-how","Help with product development and validation","Help entering international markets","Network of investors and partners","Stipend / financial support","Reputation / signalling (being selected)","Other"]'::jsonb, '{"operator":"OR","rules":[{"questionId":"7af37b44-598d-4c37-9f99-7bc44e2cc8d8","expectedValue":"Yes, I applied"},{"questionId":"7af37b44-598d-4c37-9f99-7bc44e2cc8d8","expectedValue":"I considered applying but did not submit"}]}'::jsonb, 270, true);
INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('50ddf58a-ef9a-4afe-9120-fffe563bd173', 'Section F. UzCombinator', 'Q2. Which of these was the most important single reason for you?', 'single_choice', '["Mentoring and know-how","Product / MVP support","Investor access","International expansion","Financial support","Signalling / brand","Other"]'::jsonb, '{"operator":"OR","rules":[{"questionId":"7af37b44-598d-4c37-9f99-7bc44e2cc8d8","expectedValue":"Yes, I applied"},{"questionId":"7af37b44-598d-4c37-9f99-7bc44e2cc8d8","expectedValue":"I considered applying but did not submit"}]}'::jsonb, 280, true);
INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('eb925fcb-30cf-426b-a884-ac56b343444b', 'Section F. UzCombinator', 'Q3. Before applying, how strongly did you agree with: ''UzCombinator would significantly increase my startup''s chances of long-term success.''', 'slider', '{"min":1,"max":5}'::jsonb, '{"operator":"OR","rules":[{"questionId":"7af37b44-598d-4c37-9f99-7bc44e2cc8d8","expectedValue":"Yes, I applied"},{"questionId":"7af37b44-598d-4c37-9f99-7bc44e2cc8d8","expectedValue":"I considered applying but did not submit"}]}'::jsonb, 290, true);
INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('d1a8419f-ca57-4b7f-a517-9f6e51767be6', 'Section F. Exit Plan', 'Q4. What is your current preferred exit path for your startup?', 'single_choice', '["Build for long-term cash-flow (no specific exit planned)","Sell to a local company (trade sale)","Sell to an international company (acquisition)","IPO on a local exchange","IPO on an international exchange","Not sure yet"]'::jsonb, '{"operator":"OR","rules":[{"questionId":"08bd19ee-8904-4ea8-8e1f-81ec1022cb9a","expectedValue":"I run my own business mainly because I had no better job options (necessity entrepreneur)"},{"questionId":"08bd19ee-8904-4ea8-8e1f-81ec1022cb9a","expectedValue":"I run my own business mainly because I saw a good opportunity (opportunity entrepreneur)"}]}'::jsonb, 300, true);
