INSERT INTO public.questions (id, block_name, question_text, type, options, conditional_logic, order_index, required) VALUES ('2a1a4eb9-8c21-442e-b071-cc83c4ff23e8', 'Section F. Experience with UzCombinator decisions', 'Q7. What was the outcome of your latest UzCombinator application?', 'single_choice', '["My startup was accepted","My startup was rejected","I started but did not finish the application"]'::jsonb, '{"questionId":"7af37b44-598d-4c37-9f99-7bc44e2cc8d8","expectedValue":"Yes, I applied"}'::jsonb, 330, true);
